  "supportive_card_ids": ["C01","C06","C43","C46","C21","C44","C82","C213","C255"],
  "contradictory_card_ids": ["C15","C45","C161"],
  "prediction_basis_card_ids": ["C01","C06","C43","C46","C21","C44","C82","C213","C255"],
  "claims": [
    {
      "claim": "The query is a permanently charged N-propyl quaternary ammonium ajmaline derivative; the most transferable direct gold outcomes are ipratropium (absolute oral F ≈2–3.3% in healthy volunteers across 2–20 mg) and physostigmine (F ≈1–8% in healthy volunteers), both below the 20% threshold.",
      "card_ids": ["C01","C06","C43","C46","C21","C44","C82"]
    },
    {
      "claim": "L5 provides mechanistic support for gut-wall loss of quaternary ammonium cations: N-methylscopolamine is secreted from blood into intestinal lumen (C213), and ipratropium is an intestinal OCTN2 substrate (C255); these are consistent with low oral F for the charged query, though not direct F measurements.",
      "card_ids": ["C213","C255"]
    },
    {
      "claim": "The non-quaternary parent ajmaline is absorbed from rat small intestine (C161), and some higher F outliers exist (ipratropium 32%, physostigmine 25.3%), but these are less transferable or not threshold-relevant for the quaternary query.",
      "card_ids": ["C161","C15","C45"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C213","C255"]
    }
  ],
  "evidence_gaps": [
    "No direct experimental oral bioavailability data for the query molecule (N-propyl ajmaline derivative).",
    "No permeability, efflux, or intestinal metabolism measurement for the query itself; L5 records are for other quaternary ammonium/alkaloid molecules.",
    "The explicit quaternary ammonium in SMILES conflicts with the property-tool neutral fraction of 0.98; permanent charge is a major absorption liability but its quantitative impact on this lipophilic scaffold is unknown.",
    "First-pass hepatic metabolism and intestinal secretion of the query are unknown.",
    "Some higher F outliers in less transferable contexts (ipratropium 30%, physostigmine ~25% in patients) create uncertainty around the threshold."
  ],
  "decision_summary": "Predicted low: the query is a permanently charged N-propyl quaternary ammonium ajmaline derivative; the most transferable direct gold contexts (ipratropium F ≈2–3%, physostigmine F ≈1–8% in healthy volunteers) indicate F <20%, and L5 adds mechanistic evidence for gut-wall secretion/transport of quaternary ammonium cations (C213, C255) that supports presystemic loss. L4 parent-ajmaline absorption and higher-F outliers do not overturn this because they are not direct or transferable to the charged query."
}

